use biome_analyze::{
    Ast, FixKind, Rule, RuleDiagnostic, context::RuleContext, declare_lint_rule,
};
use biome_console::markup;
use biome_diagnostics::Severity;
use biome_js_factory::make;
use biome_js_syntax::{
    AnyJsxChild, JsSyntaxKind, JsSyntaxToken, JsxChildList, JsxExpressionChild, JsxText,
};
use biome_rowan::{AstNode, BatchMutationExt, TextRange, TextSize};
use biome_rule_options::no_jsx_leaked_dollar::NoJsxLeakedDollarOptions;

declare_lint_rule! {
    /// Disallow a stray `$` before a JSX expression.
    ///
    /// When migrating from template literals to JSX, it is easy to leave behind a `$`
    /// before a `{...}` expression. The `$` is rendered as literal text, which is
    /// almost never intended.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <div>Total: ${total}</div>;
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <div>${price}</div>;
    /// ```
    ///
    /// ```jsx
    /// <div>Total: {total}</div>;
    /// ```
    ///
    /// ```js
    /// const message = `Total: ${total}`;
    /// ```
    pub NoJsxLeakedDollar {
        version: "next",
        name: "noJsxLeakedDollar",
        language: "jsx",
        recommended: false,
        severity: Severity::Warning,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoJsxLeakedDollar {
    type Query = Ast<JsxText>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoJsxLeakedDollarOptions;

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();

        // The text node must end with a `$`.
        if !text.ends_with('$') {
            return None;
        }

        // The immediately following sibling must be a JSX expression child.
        let next_sibling = node.syntax().next_sibling()?;
        if !JsxExpressionChild::can_cast(next_sibling.kind()) {
            return None;
        }

        // A lone `$` immediately before a single expression is treated as
        // intentional (e.g. displaying a currency value), when the parent
        // element only has these two children.
        if text == "$" {
            if let Some(list) = node
                .syntax()
                .parent()
                .and_then(JsxChildList::cast)
            {
                if list.len() == 2 {
                    return None;
                }
            }
        }

        Some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let end = token.text_range().end();
        let dollar_range = TextRange::new(end - TextSize::from(1), end);
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                dollar_range,
                markup! {
                    "Possible unintentional '$' before a JSX expression."
                },
            )
            .note(markup! {
